import sys, json, time
sys.path.insert(0,'/var/folders/2z/dxx4wtg91vg3krcmjmsvqg1m0000gn/T/freya-build-c7rwwl69')
import freya
st=json.load(open('.freya-agents.json'))['final-case']; agent=st['agent_id']
P=[
 {"name":"SIM single card thanks","prompt":"OUTPUT RULE: Write only the words you say on the phone, in Turkish. One or two short sentences per turn.\nYou are Melis Uçar, a Freya Bank customer calling about your credit card statement debt. You have one card. Listen to your debt. When the assistant offers anything else, say 'Teşekkürler, başka bir şey istemiyorum.' and then say goodbye.","successCriteria":"The assistant read the statement debt with amounts and the due date in Turkish and routed to the main menu.","tags":["final-test"]},
 {"name":"SIM multi card all","prompt":"OUTPUT RULE: Write only the words you say on the phone, in Turkish. One or two short sentences per turn.\nYou are Elif Toprak, a Freya Bank customer with three credit cards. Start by saying 'Bütün kartlarımın borcunu söyle'. When asked to choose one card, repeat once 'Hepsini söyle'. When asked again, say 'Yıldız Premium'. After hearing the debt, say 'Hayır, teşekkürler, başka bir şey istemiyorum.'","successCriteria":"The assistant asked which card, read only Yıldız Premium debt, and routed to the main menu.","tags":["final-test"]},
 {"name":"SIM week change","prompt":"OUTPUT RULE: Write only the words you say on the phone, in Turkish. One or two short sentences per turn.\nYou are Kerem Aksoy, a Freya Bank customer with one credit card. Listen to your debt. Then say you want to change your statement date: 'Hesap kesim tarihimi değiştirmek istiyorum.' When offered weeks, choose '3. hafta'. When the new dates are read and you are asked to confirm, first say 'Olur herhalde', then when asked again say 'Evet, onaylıyorum.' After the change is done, say 'Teşekkürler, başka bir şey istemiyorum.'","successCriteria":"The assistant read the preview dates 16 Kasım 2026 and 26 Kasım 2026, asked for explicit confirmation, made the change once, and routed to the main menu.","tags":["final-test"]},
]
made=freya.create_personas(P)["personas"]
vm={}
for p,c in zip(made,["95004361","97526380","96158684"]):
    vm[p["id"]]={"customerNumber":c,"now":"2026-10-12T10:30:00+03:00"}
sim_id,it_id,status=freya.run_simulation(agent,"final quick check "+time.strftime('%H:%M:%S'),vm,max_seconds=300,concurrency=3)
print("sim",sim_id,status)
it=freya.get_iteration(sim_id,it_id)
for r in it["runs"]:
    print("=== RUN",r.get("personaName"),"outcome",r.get("outcome"),"| reason:",str(r.get("reason"))[:400])
    try:
        call=freya.get_call(r["callId"])
    except Exception as e:
        print("call err",e); continue
    for m in call.get("messages",[]):
        role=m.get("role"); msg=m.get("message")
        if role=="system":
            try: ev=json.loads(msg)
            except Exception: ev={}
            e=ev.get("event")
            if e=="function_call_start": print("  [call]",ev.get("function"),json.dumps(ev.get("args",{}).get("body"),ensure_ascii=False)[:300])
            elif e=="function_call_complete": print("  [result]",ev.get("function"),json.dumps(ev.get("result"),ensure_ascii=False)[:300])
            elif e=="error": print("  [ERROR]",str(ev)[:400])
            elif e=="node_enter": print("  [node]",ev.get("node"))
        else:
            print(" ",role.upper()+":",str(msg)[:600])
    print("  ended:",call.get("endedReason"))
EOF
python3 /tmp/sim.py > /tmp/sim.out 2>&1; echo done; date

