    except Exception as e: print("call err",e); continue
    for m in call.get("messages",[]):
        role=m.get("role"); msg=m.get("message")
        if role=="system":
            try: ev=json.loads(msg)
            except Exception: ev={}
            if ev.get("event")=="function_call_start" and ev.get("function")=="api_call": print("  [call]",json.dumps(ev.get("args",{}).get("body"),ensure_ascii=False)[:200])
            elif ev.get("event")=="error": print("  [ERROR]",str(ev)[:300])
        else: print(" ",role.upper()+":",str(msg)[:400])
    print("  ended:",call.get("endedReason"))
